import React, { useEffect, useState } from 'react';
import axios from 'axios';
import { useNavigate } from 'react-router-dom';
import styles from './Communities.module.css';
import CommunityCard from './CommunityCard';

const CommunitiesDiscovery = () => {
    const navigate = useNavigate();
    const [communities, setCommunities] = useState([]);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        const fetchDiscovery = async () => {
            try {
                setLoading(true);
                const resp = await axios.get('http://10.124.215.133:8000/api/communities/', {
                    headers: { 'Authorization': `Bearer ${localStorage.getItem('access')}` }
                });
                setCommunities(resp.data.results || resp.data || []);
            } catch (err) {
                console.error(err);
            } finally {
                setLoading(false);
            }
        };
        fetchDiscovery();
    }, []);

    return (
        <div className={styles.communities_out_container}>
            <div className={styles.main_container}>
                

                <header className={styles.main_header}>
                    <div className={styles.main_header_left}>
                        <div className={styles.main_item} onClick={() => navigate('/')}>
                            <img className={styles.main_header__img_logo} src="/images/logo.svg" alt="logo" />
                        </div>
                    </div>
                    <div className={styles.main_header_right}>
                        <div className={styles.main_item}>
                            <img className={styles.main_header__img} src="/images/bell.svg" alt="notifications" />
                        </div>
                        <div className={styles.main_item}>
                            <img className={styles.main_header__img} src="/images/back.svg" alt="back" onClick={() => navigate(-1)} />
                        </div>
                    </div>
                </header>

                <div className={styles.main_afterheader}>
                    <div className={styles.main_afterheader__item} onClick={(e)=>navigate('/')}>Главная</div>
                    <div className={styles.main_afterheader__item} onClick={(e)=>navigate('/communities')}>Сообщества</div>
                    <div className={styles.main_afterheader__item}>Сообщения</div>
                </div>


                <div className={styles.communities_body}>
                    {loading ? (
                        <div style={{textAlign: 'center', padding: '20px', fontSize: '1.5rem'}}>Загрузка... 🎲</div>
                    ) : (
                        communities.map((comm) => (
                            <CommunityCard key={comm.id} community={comm} />
                        ))
                    )}
                </div>



                <div className={styles.communities_bottom__panel}>
                    <div className={styles.communities_bottom__item} onClick={() => navigate('/')}>
                        <img className={styles.communities_bottom__img} src="/images/home.svg" alt="home" />
                    </div>
                    <div className={styles.communities_bottom__item}>
                        <img className={styles.communities_bottom__img} src="/images/search.svg" alt="search" />
                    </div>
                    <div className={styles.communities_bottom__item} onClick={() => navigate('/create-post')}>
                        <img className={styles.communities_plus__img} src="/images/plus.svg" alt="plus" />
                    </div>
                    <div className={styles.communities_bottom__item}>
                        <img className={styles.communities_bottom__img} src="/images/chat.svg" alt="chat" />
                    </div>
                    <div className={styles.communities_bottom__item} onClick={() => navigate('/profile')}>
                        <img className={styles.communities_bottom__img} src="/images/profile.svg" alt="profile" />
                    </div>
                </div>

            </div>
        </div>
    );
};

export default CommunitiesDiscovery;
